$rows=@();$previous=$null;$parent=$null
for($i=0;$i -lt $items.Count;$i++) {
 $item=$items[$i];$bodyPath="artifacts/living-ornament/ticket-$i.md";$item.body | Set-Content $bodyPath
 $raw=& $exe --home $dataHome ticket create --title $item.title --body-file $bodyPath --assigned-to $agent --session $session --request "ornament-create-$i-v1" --json
 if($LASTEXITCODE -ne 0){throw $raw};$created=($raw|ConvertFrom-Json).data
 $deps=@();if($i -gt 1){$deps=@($previous)}
 $spec=@{title=$item.title;body=$item.body;kind=$item.kind;parent_id=$parent;dependencies=$deps;reason='User approved batched roadmap and implementation with visual and artistic iteration.'}
 $specPath="artifacts/living-ornament/spec-$i.json";$spec|ConvertTo-Json -Depth 5|Set-Content $specPath
 $raw=& $exe --home $dataHome ticket edit $created.id --session $session --expect-revision $created.revision --body-file $specPath --request "ornament-spec-$i-v1" --json
 if($LASTEXITCODE -ne 0){throw $raw};$edited=($raw|ConvertFrom-Json).data
 $rows+= $edited
 $rows|ConvertTo-Json -Depth 12|Set-Content artifacts/living-ornament/tickets.json
 if($i -eq 0){$parent=$created.id}else{$previous=$created.id}
 [pscustomobject]@{key=$edited.display_key;id=$edited.id;revision=$edited.revision;title=$edited.title;state=$edited.state}|ConvertTo-Json -Compress
}
